preConditionHook:
// Signal bar = the bar before the entry bar = bar [1] on the fill bar, where
// BarsSinceEntry() is 0 (EL_FEATURES.md `barssinceentry`, VERIFIED). Captured
// once instead of indexed by the position's age every bar, which keeps the
// deepest subscript at 1.
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    sigLow = low[1];
    sigHigh = high[1];
}
